import math
def control(o):
    h=o['hitch_deg']
    v=o.get('views',{}).get('camera')
    steer=2.0*h
    if v and v.get('walls'):
        pts=[]
        for b,d in v['walls']:
            a=math.radians(b-o['rig']['trailer_heading_deg'])
            x=d*math.cos(a); y=d*math.sin(a)
            if x < -1 and x > -7: pts.append((x,y))
        left=[y for x,y in pts if y>0.5]; right=[y for x,y in pts if y< -0.5]
        if left and right:
            c=(min(left)+max(right))/2
            steer+=max(-12,min(12,-5*c))
    return (max(-28,min(28,steer)),-0.8,-23)

